function advanceTrapsKing(s,king){
  // 静态敌子只有走法形状已覆盖将帅时，才可能因调子解除阻挡或增加炮架而形成进攻。
  const shape=p=>p.kind==='cannon'?(p.x===king.x||p.y===king.y):E.geometry({pieces:[p,king]},p,king.x,king.y,true);
  const aligned=s.pieces.filter(p=>{
    if(p.side===king.side||!shape(p))return false;
    if(p.kind==='cannon')return E.between(s,p,king.x,king.y).length<=2;
    return !['rook','king'].includes(p.kind)||E.between(s,p,king.x,king.y).length<=1;
  });
  return s.pieces.some(p=>{
    if(p.side===king.side)return false;
    // 短程棋子连续移动和攻击的单轴跨度至多为 4；没有静态攻击者时可排除更远的调子。
    if(!aligned.length&&!['rook','cannon','king'].includes(p.kind)&&(p.x<king.x-4||p.x>king.x+4||p.y<king.y-4||p.y>king.y+4))return false;
    const stationary=aligned.filter(q=>q.id!==p.id);
    return E.moves(s,p).filter(m=>!E.at(s,m.x,m.y)).some(m=>{
      const moved={...p,x:m.x,y:m.y};
      if(!stationary.length&&!shape(moved))return false;
      const projected={...s,pieces:s.pieces.map(q=>q.id===p.id?moved:q)};
      // 调动可能给另一枚棋子建立炮架或解除挡线，攻击者不一定是移动者。
      if(![moved,...stationary].some(q=>E.canMove(projected,q,king.x,king.y)))return false;
      const next={...s,pieces:s.pieces.map(q=>({...q})),repetitions:{...s.repetitions},log:[...s.log]};
      E.move(next,p.id,m.x,m.y);
      if(next.phase!=='board'||!threatCost(next,E.get(next,king.id)))return false;
      const defender=E.get(next,king.id);
      return E.moves(next,defender).filter(exit=>!E.at(next,exit.x,exit.y)).every(exit=>{
        const escaped={...next,pieces:next.pieces.map(q=>({...q})),repetitions:{...next.repetitions},log:[...next.log]};
        E.move(escaped,king.id,exit.x,exit.y);
        return escaped.phase==='board'&&threatCost(escaped,E.get(escaped,king.id))>0;
      });
    });
  });
}

